import test from'node:test';import assert from'node:assert/strict';import fs from'node:fs';import path from'node:path';import os from'node:os';import{pathToFileURL}from'node:url';
const moduleRoot=process.env.DSH_PURGE_TEST_ROOT?pathToFileURL(path.resolve(process.env.DSH_PURGE_TEST_ROOT)+'/'):new URL('../',import.meta.url),manifest=JSON.parse(fs.readFileSync(new URL('package.json',moduleRoot))),boot=await import((process.env.DSH_PURGE_TEST_APP_BOOT?pathToFileURL(path.resolve(process.env.DSH_PURGE_TEST_APP_BOOT)):new URL('../../../runtime/node_modules/@deepseek-ai/dsh-app-boot/lib/index.js',import.meta.url)));
test('actual app-boot admits exact alpha and rc2 runtime hooks without exemption but rejects unreviewed versions',()=>{for(const version of['0.2.1-alpha.1','0.2.1-rc.2'])assert.equal(boot.evaluatePluginCompatibility(manifest,{},version),undefined,version);for(const version of['0.2.1-alpha.2','0.2.1-rc.3','0.2.2']){const issue=boot.evaluatePluginCompatibility(manifest,{},version);assert(issue);assert.equal(issue.exempted,false);}assert.equal(Object.keys(manifest.peerDependencies).filter(name=>name.startsWith('@deepseek-ai/dsh-')).length,4);});
test('actual rc2 profile bundle loader keeps purge layer and exact user enabled override, no allow-version file',()=>{const root=fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(),'dsh-purge-bundle-'))),pkg=root+'/node_modules/dsh-purge',profile=root+'/home/profiles/phone',anchor=root+'/package.json',user='- id: dsh-purge\n  disabled: false\n  config:\n    enabled: true\n';try{fs.mkdirSync(pkg,{recursive:true});fs.mkdirSync(profile,{recursive:true});fs.writeFileSync(pkg+'/package.json',JSON.stringify(manifest));fs.copyFileSync(new URL('cordis.patch.yml',moduleRoot),pkg+'/cordis.patch.yml');fs.writeFileSync(anchor,'{}');fs.writeFileSync(profile+'/package.json',JSON.stringify({name:'phone-fixture',private:true,dsh:{profile:{bundles:['dsh-purge']}}}));fs.writeFileSync(profile+'/cordis.patch.yml',user);const before=fs.readFileSync(profile+'/package.json','utf8');const loaded=boot.loadProfileDirectory('fixture',profile,anchor);assert.deepEqual(loaded.skippedBundles,[]);assert.equal(loaded.layers.length,1);assert.equal(loaded.layers[0].packageName,'dsh-purge');assert.equal(loaded.patches[0].disabled,false);assert.equal(loaded.patches[0].config.enabled,true);assert.equal(fs.readFileSync(profile+'/cordis.patch.yml','utf8'),user);assert.equal(fs.readFileSync(profile+'/package.json','utf8'),before);assert(!fs.existsSync(profile+'/plugin-compatibility.json'));}finally{fs.rmSync(root,{recursive:true,force:true});}});
